INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (30, "Carnival", "Casual family-friendly Fun Ship 2.0 energy; leans into fun over formality; loud lido decks and comedy clubs.", "US short-cruise portfolio; mid-value tier; 30+ ship fleet; oldest mass-market player in Caribbean.", "Carnival is generous with category guarantees (4A 4B 4C) where they assign tier within 48h of sailing and often bump up one category for free. Balcony premium is worth it only on 7+ nights where you actually sit outside. Excel-class cabins size up well.", "Off-ship operators run 30-50% cheaper than ship tours on Caribbean ports. Use ship excursions only for tender ports or remote Belize and Grand Cayman stops where independent logistics cost more than they save.", "Forward lowest-deck cabins get anchor noise. Aft cabins above elevators get foot traffic. Specialty dining on 3-night sailings never breaks even.", "First-time cruisers; groups; value-oriented families; anyone who disliked the formality of dressier lines.", "Carnival frequently bundles 50-100 onboard credit with balcony+ bookings 60-90 days out. VIFP loyalty tiers unlock priority boarding and beverage discounts past Blue. Signature attractions include WaterWorks slides and Lido Dive-In Movies.", 12);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (38, "Celebrity Cruises", "Modern luxury for grownups; polished Edge-class design; food-driven but not stuffy; quiet luxury without the sticker shock.", "Premium-contemporary tier; capital M menu; Edge-class is flagship; sister brand to Royal Caribbean but positioned as quiet premium.", "Sky Class suites pay back only if you use premium dining (Luminae) and drink package - otherwise Retreat access is wasted money. Edge-class Magic Carpet is novel but deck 14 cabins near it get dual-channel noise. AquaClass is worth the upgrade only if you want Blu and Persian Garden spa access.", "For Naples and Athens book ship tours - local knowledge and guide quality matter. For Rome Florence and Barcelona book independently with 30% savings via Viator or local operators; just leave 90 minutes of buffer for return-to-ship.", "Interior staterooms on 4-night sailings are tight. Mid-January and mid-March shoulder sailings sometimes drift to dead-month pricing but cabin selection is limited.", "Couples; foodies; celebrant adults; bus-tour-free ports; anyone who outgrew mass-market carnival lido energy.", "All Included package bundles drink Wi-Fi and gratuities at a real discount. Celebrity frequently stages Go Big Better Best offers around stage season with free Wi-Fi and OBC included.", 9);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (34, "Royal Caribbean", "Activity-driven mega-ship-within-a-ship scale; attractions-rivals-coasters energy; broad appeal with quiet adults-only Solarium retreat.", "Oasis-class and Icon-class megaships with neighbourhood concepts; Royal Suite Class gives butler service on top deck; mass-market volume leader.", "Central Park-view balconies are the most-cited value win on Oasis-class ships; you pay balcony price for a leafy calm view without paying Boardwalk markup. Avoid Promenade-view interior - noisy and claustrophobic. Star Class suites earn Genie and Coastal Kitchen but only on 7+ nights.", "Perfect Day at CocoCay is the line-owned pricing floor - the free beaches and included food beat most third-party Caribbean excursions. For third-party ports Cozumel and Nassau have rich independent options; book Viator. Labadee is Royal-owned Haiti compound - no independent options worth the safety tradeoff.", "Boardwalk-view balconies get the carousel noise and AquaTheater show reverb. Low-deck forward cabins get pool deck drag-anchor noise. Solarium is adult-only at 16+ not 18+.", "Families with teens; multi-gen groups; activity cruisers; first-timers who want scale without paying luxury prices.", "Royal Genie and Coastal Kitchen only on Star Class suites. Crown and Anchor Society loyalty tiers unlock Diamond Lounge access from Diamond and above. Signature attractions across fleet include FlowRider surf simulator; Perfect Day water park; Ultimate Abyss slide on Oasis-class.", 11);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (35, "Norwegian Cruise Line", "Freestyle cruising; no fixed dining times no dress code; solo cruiser pioneer (Studio cabins); onboard vibe skews younger and louder.", "Mass-market; Breakaway-class and Prima-class recent builds; The Haven is ship-within-a-ship luxury enclave.", "The Haven suites earn private restaurant private pool and butler - worth it on 7+ nights or family trips. Studio cabins are real single cabins with no single supplement - the only honest solo option in mass-market. Balcony guarantee is a good lottery on Prima-class; less reliable on older Breakaway.", "NCL private island Harvest Caye is well-built but ticketed a la carte - food is included but excursions cost extra. For Caribbean public ports book independently. For Alaska and Greek Isles ship tours have real value due to limited independent infrastructure.", "Inside cabins on Breakaway-class get bunk-bed only layouts in some categories - check deck plans. Forward cabins on Prima-class get noise from theater above. Specialty dining package on 4-night sailings never breaks even.", "Solo cruisers; multi-gen families who want flexibility; non-formal travelers; groups who can not agree on dinner time.", "Free at Sea promo bundles specialty dining drink package and excursions - but watch the 20% service charge on each perk. Latitudes Rewards loyalty program gives basic priority boarding at Platinum tier.", 10);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (31, "Princess Cruises", "Romantic traditional mid-premium; original Love Boat line; polished culinary caliber; adult-skewing but family-friendly.", "Mid-premium; Royal-class and Discovery-class; MedallionClass tech across fleet; Carnival Corp sister to Holland America but warmer vibe.", "Mini-suites offer real space bump for modest premium - better value than full suite. Balcony guarantee is well-priced on Alaska routes; less interesting on Caribbean. Reserve Collection premium dining is a serious upgrade with Sabatinis and Crown Grill.", "Princess private island Princess Cays is good stop but cabanas sell out early. Alaska shore excursions are the Princess strength - book early since 60% sell out before departure. For Mediterranean sailings book independently on Italy-Spain stops; book ship in Greek isles and Turkey.", "Forward cabins on Royal-class get theater bass reverb. Interior on 4-night Mediterranean sailings are claustrophobic for the price. Specialty dining package has narrow value window - run the math.", "Couples; older travelers; Alaska-first cruisers; refined-but-not-luxury seekers.", "Captain Circle loyalty members get priority tender and members-only sailings. Plus package bundles drink and specialty dining. Signature experiences: Movies Under the Stars; MedallionClass digital ordering and keyless entry; Chef Table tasting menu.", 13);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (32, "Holland America Line", "Traditional refined premium; cuisine-trained culinary council; older-skewing demographic; classical-music and enrichment programming.", "Premium; Pinnacle-class and Signature-class; 11-ship fleet; Carnival Corp sister to Princess but Holland America leans older, quieter, more destination-forward.", "Balcony guarantee on 7+ night Europe and Alaska sailings is a genuine value - HAL assigns well and rarely punitively. Neptune Suite gets exclusive Neptune Lounge with concierge - worth it on 14+ night sailings. Interior on HAL is unusually small - book balcony only if budget permits.", "HAL excursions are curated well and use smaller operators - in Northern Europe and Canada/New England ship tours have real merit due to limited infrastructure. For Caribbean public ports book independently. EXC In-Depth Adventure series focuses on active shore options like kayak hikes and cooking classes.", "Forward cabins on Pinnacle-class get Darby vibration from thrusters. Lower decks have older HVAC hum. Late dining fills fast - book main dining at booking.", "Mature cruisers; solo travelers (good single supplements); foodies; destination-forward travelers; Alaska and Northern Europe first-timers.", "Mariner Society loyalty program for past passengers. Have It All package bundles drink dining gratuities and shore excursion credit. Signature: Americas Test Kitchen cooking demos; Lincoln Center Stage chamber music; Bb Kings Blues Club.", 14);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (36, "MSC Cruises", "European-flavored mass-market; glitz and grand atriums; family-friendly; infants sail free; extensive Mediterranean positioning.", "World Yacht Club and Meraviglia-class; aggressively expanding into US market; value-tier Caribbean deployments from Port Canaveral and Miami.", "MSC Yacht Club is ship-within-a-ship luxury with private restaurant pool and butler - real value compared to Royal Genie or NCL Haven at lower price. Bella is the cheap interior - small but adequate for 3-night sailings. Balcony on Meraviglia-class is generous and well-priced.", "MSC private island Ocean Cay is improved but still developing; food included. For Caribbean public ports MSC excursions are overpriced vs Viator. For Mediterranean sailings book independently with the standard 30% savings; MSC tours are heavily tourist-trail.", "MSC stretches port times shorter than competitors - watch itinerary math. MSC-for-Me app fees for basic services like booking restaurant. Yacht Club suite guests still pay for some premium dining.", "European travelers; budget Caribbean cruisers; families with infants and young kids; Mediterranean-first itinerary seekers.", "MSC Voyagers Club has 5% repeat-guest discount starting at first repeat. Fantastica package gets priority boarding. Kids sail free promotions are frequent.", 8);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (33, "Cunard Line", "Traditional British ocean-liner heritage; black-tie formal nights; transatlantic crossings; refined theatrical and literary programming.", "Premium-ultra; Queen Mary 2 Queen Elizabeth Queen Victoria; 3-ship fleet; smallest of the premium lines and the only true ocean liner in service.", "Princess Grill and Queens Grill suites earn Grill-class restaurant access - the real upgrade; worth it on transatlantic crossings where the experience IS the destination. Britannia Club balcony is the sweet spot - Britannia restaurant access but with club-class dining flexibility. Interior Britannia is fine for under-7-night crossings only.", "Cunard excursions are curated and expensive but worth it on maiden and transatlantic ports - independent options are thin in Southampton Hamilton and Bergen. For Mediterranean and Caribbean book independently. World Voyage segment shore excursions are bucket-list quality.", "Informal nights are still a notch above other lines formal. Childrens programs are limited - not a family line. Britanniabuffet dining feels mass-market compared to restaurant.", "Traditionalists; transatlantic romantics; older couples; literature and classical-music lovers; bucket-list World Cruisers.", "Cunard Fare includes gratuities and some drinks. World Club loyalty discounts. Signature: Transatlantic Crossing on Queen Mary 2; Royal Astronomical Society planetarium; kennel program for pets on QM2.", 16);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (37, "Disney Cruise Line", "Premium family; Disney characters meet Disney classics storytelling; refined dining rotation; adults-only areas hidden away.", "Premium; Disney Wish Disney Magic Disney Wonder Disney Dream Disney Fantasy Disney Treasure; 5+ ship fleet; notoriously the most expensive mass-market family cruise line.", "Concierge suites earn pre-booking for excursions dining and Castaway Cabanas - worth it on 7+ nights. Verandah cabins are standard, and the larger-than-peer-cruise verandah is the family value win. Interior on 3-night sailings is fine - kids sleep in the bunk and you barely use the room.", "Castaway Cay is Disneys private island in Bahamas - book early; the family beach is included, but cabanas and excursions (snorkel, bike) sell out 6+ months out. For Mediterranean sailings Disney tours have Disney-trained guides - quality premium. For Alaska Disney excursions are well done but NCL and HAL have similar quality.", "Pirate Night on 3+ night sailings is loud and crowded. Adult dining (Palo and Enchant) competes with main dining rotation - tasting menu is worth it but book at booking. Disney prices rarely go down - book early for best cabin selection.", "Families with kids 4-14; multi-generational Disney-first families; special-needs travelers (Disneys accessibility is best-in-class); Disney fans.", "Disney Cruise Line Navigator app is genuinely useful. Castaway Club loyalty unlocks early booking and small perks. Signature: Disney characters; rotational dining; Buena Vista Theatre first-run movies; Pirate Night fireworks.", 11);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (39, "Virgin Voyages", "Adults-only modern; zero kids anywhere; onboard vibe is rooftop-club-meets-designer-hostel; tattoo parlor and record shop onboard.", "Adults-only premium-contemporary; Scarlet Lady Valiant Lady Resilient Lady Brilliant Lady; 4-ship fleet; targets 30-50 year olds who want adults-only without the Cunard formality.", "Sea Terrace cabins are the line-defining value - balcony space real desk lighting bluetooth speaker. Solo suites (RockStar Quarters) are a real adults-only solo option. Interior is small but adequate - itinerary-first cruisers use it well.", "Virgin Voyages Beach Club at Bimini is the private stop - included food and beach club vibe is more like Miami Beach day club than cruise shore excursion. For Caribbean public ports book independently; Virgin curated tours are me-too.", "Adults only means no kids - if you wanted family cruise avoid. Late-night shows start 10:30 PM and run past midnight - book rooms midship for cabin noise control. The Sailor Loot promotional WiFi is metered - upgrade to higher-tier package for video.", "Couples; groups of friends; solo travelers; honeymoon and bachelor-bachelorette parties; 30-50 demographic first-time cruisers.", "Sailing Loot bundles WiFi and basic drinks. No tipping required - gratuities included. Signature: Squid Ink tattoo parlor; Redemption spa with thermal suite; Manor nightclub; Galley 7 food court.", 5);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (40, "Oceania Cruises", "Upscale mid-luxury with the best food at sea by a long margin; refined destination-forward; executive chef on every ship; thermal-suite spa culture.", "Mid-luxury premium; Regatta-class and Vista-class; 6-ship small fleet; smaller ships (640-1200 pax) get into ports larger ships can not manage.", "Penthouse Suites earn butler and premium dining - worth it on 10+ night sailings when you actually use the service. Concierge Level Verandah is the sweet spot for value - bonus amenities without full suite pricing. Interior staterooms are small but well-designed - fine for itinerary-first cruisers, not recommended for 10+ night sailings.", "Oceania destinations are curated ports of call - the line chooses ports larger ships skip. For Mediterranean and Northern Europe book Oceania tours - they use small-group local operators. For Caribbean book independently. Go Local tours provide real local-host experience.", "Oceania is adult-skewing (no kid programming). Older demographic. Smaller ships roll more in open water - sea days can be rough.", "Foodies; destination-first travelers; experienced cruisers looking for the next tier up; couples; adults-only vacationers.", "Oceania Club has multiple repeat-guest discounts. Free specialty dining - all restaurants included. Signature: Culinary Center cooking classes; Artist Loft art classes; full thermal suite spa included for suite guests.", 14);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (42, "Azamara Club Cruises", "Boutique destination-immersion luxury; longer stays and overnights in port; smaller ship feel similar to Oceania but with more guided debark talks.", "Luxury-boutique; Azamara Journey Azamara Quest Azamara Pursuit Azamara Onward; 4-ship fleet of 700-pax ships; the line that popularized destination immersion over ship-as-destination.", "Club Continent Suites earn butler and 240 minutes of free phone calls - worth it on World Journey segments. Club Veranda is the standard sweet spot. Interior Club Oceanview is small but the value is the itinerary not the cabin - book if itinerary-forward.", "Azamara signature AzAmazing Evenings are included cultural experiences in port - do not miss. For overnight ports (Istanbul, St. Petersburg in good years, Amsterdam) book late-night dining or nightlife tours independently. White Night deck party is a line signature.", "Smaller ships roll in open ocean - sea days between ports can be rough. Smaller demographic so solo cruisers have less noise. No basketball court or large-scale entertainment.", "Experienced cruisers who outgrew mass-market; cultural travelers; couples; solo travelers; port-heavy itinerary seekers.", "Azamara Circle loyalty discounts. Select beverage package bundled. Signature: AzAmazing Evenings cultural event; White Night deck party; Destination Specialists onboard lecturers; complimentary shuttle service in some ports.", 19);
INSERT OR REPLACE INTO line_guides (cruise_line_id, cruise_line_name, personality, fleet_position, cabin_strategy, excursion_strategy, what_avoid, best_for, onboard_concessions, fleet_avg_age_years) VALUES (41, "Seabourn Cruise Line", "Ultra-luxury all-inclusive; champagne-flowing country-club-energy; small ships in remote ports; culinary team from Thomas Keller collaboration.", "Ultra-luxury; Seabourn Odyssey-class and Seabourn Encore-class; 7-ship fleet of 450-600 pax ships; the only ultra-luxury line with real expedition capability in Antarctica.", "All suites - no interior cabins - so no down-class worry. Veranda Suites are the standard-bearer and value. Owners Suites pay back only on World Cruise segments or 14+ day sailings where service differentiation matters.", "Seabourn Ventures are expedition-style shore experiences in Alaska Antarctica and Norway; book these over standard excursions - quality is meaningfully better. In standard port calls Seabourn-curated excursions are real value compared to mass-market; for Mediterranean book independently with the standard 30% savings.", "All-inclusive pricing means all-inclusive shopping - low-end talent shows are not your speed. Older demographic heavily skews 55+. Formal nights are opt-in but the country club formality is the default.", "Ultra-luxury travelers transitioning from premium; retired or affluent couples; expedition Antarctica first-timers; travelers who want all-inclusive pricing without nickel-and-diming.", "Seabourn Club loyalty gets free laundry and 5% repeat-guest rate. All alcohol included in fare. Signature: Thomas Keller Restaurant on Encore-class; Ventures by Seabourn expedition team; Encore Suite outdoor living room; The Club live music venue.", 10);
